const prospects = [];
const visits = [];
const savedDraft = JSON.parse(localStorage.getItem('radar-route-draft') || '[]');
const state = { selected:null, view:'overview', regions:[], regionFilter:null, userLocation:null, nearbyProspectIds:[], routeStops:Array.isArray(savedDraft)?savedDraft:[], dashboard:{}, overviewMap:null, routeMap:null, overviewLayer:null, routeLayer:null };
const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const html=(value='')=>String(value).replace(/[&<>'"]/g,(char)=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const number=(value)=>Number(value||0).toLocaleString('pt-BR');

function priorityLabel(level){return level==='high'?'Alta':level==='medium'?'Média':'Baixa'}
function moneyRange(min,max){if(min==null&&max==null)return 'A qualificar';const brl=(value)=>Number(value||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});return min!=null&&max!=null?`${brl(min)}–${brl(max)}`:brl(max??min)}
function makeInitials(name=''){return name.split(/\s+/).filter(Boolean).slice(0,2).map((part)=>part[0]).join('').toUpperCase()||'--'}
function toProspect(row){return {id:row.id,name:row.trade_name||row.company_name,initials:makeInitials(row.trade_name||row.company_name),color:'#557b68',segment:row.segment||'A classificar',cityName:row.city||'',state:row.state||'',city:[row.city,row.state].filter(Boolean).join(' · ')||'Local a confirmar',priority:row.priority||'medium',score:Number(row.score||0),potential:moneyRange(row.potential_min,row.potential_max),status:({new:'Novo',qualify:'Qualificar',contacted:'Contato feito',review:'Revisar dados'})[row.status]||row.status,products:(row.product_families||[]).join(', ')||'A confirmar',confidence:Number(row.confidence||0),reasons:(row.score_reasons||[]).length?row.score_reasons:['Aguardando qualificação'],cnpj:row.cnpj||'Não informado',address:row.address||'Endereço a confirmar',latitude:row.latitude==null?null:Number(row.latitude),longitude:row.longitude==null?null:Number(row.longitude)}}
function toVisit(row){const date=new Date(row.visited_at);return {date:date.toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}).replace('.',''),time:date.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}),company:row.company_name,city:row.city||'',seller:row.seller_name,initials:makeInitials(row.seller_name),result:row.result,kind:row.result.includes('Oportunidade')?'success':row.result.includes('ausente')?'warn':'neutral',next:row.next_action||'A definir'}}
async function api(url,options={}){const response=await fetch(url,options);if(response.status===401){window.location.replace('/login.html');throw new Error('Sessão expirada.')}const data=response.status===204?null:await response.json();if(!response.ok)throw new Error(data?.error||'Falha na operação.');return data}

function prepareLiveUi(){
  const metricLabels=['Prospects cadastrados','Alta prioridade','Clientes do ERP','Cidades mapeadas'];
  const metricNotes=['Fonte externa + cadastro da equipe','Na fila atual','Base de clientes sincronizada','Território atual e expansão'];
  $$('.metric-card').forEach((card,index)=>{const label=$('span',card),note=$('small',card);if(label)label.textContent=metricLabels[index];if(note){note.className='';note.innerHTML=`<em>${metricNotes[index]}</em>`}});
  $('.map-wrap').innerHTML='<div id="overviewMap" class="live-map" aria-label="Mapa real dos territórios comerciais"></div><div class="map-legend"><span><i class="current-dot"></i>Atual</span><span><i class="potential-dot"></i>Expansão</span><span><i class="high-dot"></i>Prospect</span></div>';
  $('.large-route-map').innerHTML='<div class="map-toolbar"><span><i></i>Mapa geográfico real</span><button data-action="recenter" aria-label="Centralizar"><svg><use href="#icon-focus"></use></svg></button></div><div id="routeMap" class="live-map"></div><div class="route-map-note"><svg><use href="#icon-map"></use></svg><div><strong>Mapa OpenStreetMap</strong><p>Pontos e distâncias calculados com coordenadas reais.</p></div></div>';
  const intro=$('#routesView .page-intro');$('h1',intro).textContent='Planejar rota';$('p:not(.eyebrow)',intro).textContent='Selecione uma região, adicione prospects reais e envie os destinos ao Waze.';
  $('.route-actions',intro).innerHTML='<button class="secondary-button" data-action="sync-sheet">Sincronizar planilha</button><button class="secondary-button" data-action="share-whatsapp">Enviar no WhatsApp</button><button class="primary-button" data-action="optimize-route"><svg><use href="#icon-spark"></use></svg>Ordenar por proximidade</button>';
  $('.activity-card').innerHTML='<div class="panel-header"><h2>Origem dos dados</h2></div><div class="activity-row"><span class="activity-icon success"><svg><use href="#icon-check"></use></svg></span><div><strong>Territórios da aba Varejo</strong><p id="regionDataStatus">Aguardando sincronização</p></div></div><div class="activity-row"><span class="activity-icon neutral"><svg><use href="#icon-refresh"></use></svg></span><div><strong>Base de clientes</strong><p id="customerDataStatus">Aguardando sincronização</p></div></div>';
  $('.route-timeline .timeline-summary').innerHTML='<div><span id="routeStopCount">0</span><small>paradas</small></div><div><span id="routeDistance">0 km</span><small>linha estimada</small></div><div><span id="routeLocated">0</span><small>geolocalizadas</small></div><div class="saving"><span id="routeRegionName">—</span><small>região selecionada</small></div>';
  $('.route-card').innerHTML='<div class="route-date"><strong id="routeDraftCount">0</strong><span>PARA<br>DAS</span></div><div class="route-info"><span class="eyebrow">ROTA EM PREPARAÇÃO</span><h3 id="routeDraftTitle">Nenhuma parada adicionada</h3><p id="routeDraftInfo">Escolha prospects reais para montar a navegação.</p></div><div class="route-saving"><span id="syncStatus">Verificando sincronização…</span><small>Google Sheets → Neon</small></div><button class="secondary-button" data-view-link="routes">Revisar rota</button>';
  $('.add-stop').innerHTML='<svg><use href="#icon-plus"></use></svg>Adicionar prospect';
  const date=new Date();$('#overviewView .page-intro .eyebrow').textContent=date.toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).toUpperCase();$('#overviewView .page-intro h1').textContent='Bom dia, Thiago.';
}
function initMaps(){if(!window.L)return;state.overviewMap=L.map('overviewMap',{zoomControl:true}).setView([-22.7,-46.4],7);state.routeMap=L.map('routeMap',{zoomControl:true}).setView([-22.7,-46.4],8);for(const map of [state.overviewMap,state.routeMap])L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(map);state.overviewLayer=L.layerGroup().addTo(state.overviewMap);state.routeLayer=L.layerGroup().addTo(state.routeMap)}
function validPoint(item){return Number.isFinite(Number(item.latitude))&&Number.isFinite(Number(item.longitude))}
function fitMap(map,points,fallback=[-22.7,-46.4]){if(!map)return;if(!points.length)return map.setView(fallback,7);if(points.length===1)return map.setView(points[0],11);map.fitBounds(points,{padding:[25,25],maxZoom:11})}
function renderOverviewMap(){if(!state.overviewMap)return;state.overviewLayer.clearLayers();const points=[];for(const region of state.regions){if(Number.isFinite(Number(region.hubLatitude))&&Number.isFinite(Number(region.hubLongitude))){const point=[Number(region.hubLatitude),Number(region.hubLongitude)];points.push(point);L.circleMarker(point,{radius:8,color:'#142758',weight:3,fillColor:'#fff',fillOpacity:1}).bindPopup(`<strong>${html(region.name)}</strong><br>Polo: ${html(region.hubCity)}/${html(region.hubState)}<br>Vendedor: ${html(region.sellerName||'não informado')}`).addTo(state.overviewLayer)}for(const city of region.cities.filter(validPoint)){const point=[Number(city.latitude),Number(city.longitude)];points.push(point);const current=city.source==='current';L.circleMarker(point,{radius:current?4:3,color:current?'#247259':'#c18b36',weight:1,fillOpacity:.75}).bindTooltip(`${html(city.city)}/${html(city.state)} · ${Math.round(city.distanceKm||0)} km`).addTo(state.overviewLayer)}}for(const prospect of prospects.filter(validPoint)){const point=[prospect.latitude,prospect.longitude];points.push(point);L.circleMarker(point,{radius:7,color:'#fff',weight:2,fillColor:'#d9624d',fillOpacity:1}).bindPopup(`<strong>${html(prospect.name)}</strong><br>${html(prospect.segment)}<br><button class="map-detail" data-select="${html(prospect.id)}">Abrir oportunidade</button>`).addTo(state.overviewLayer)}fitMap(state.overviewMap,points)}
function selectedRegion(){return state.regions.find((region)=>region.id===$('#regionSelect')?.value)||state.regions[0]}
function renderRouteMap(){if(!state.routeMap)return;state.routeLayer.clearLayers();const region=selectedRegion(),points=[];if(region){for(const city of region.cities.filter(validPoint)){const point=[Number(city.latitude),Number(city.longitude)];points.push(point);const current=city.source==='current';L.circleMarker(point,{radius:current?5:4,color:current?'#247259':'#c18b36',weight:2,fillOpacity:.7}).bindPopup(`<strong>${html(city.city)}/${html(city.state)}</strong><br>${current?'Território atual':'Expansão'} · ${Math.round(city.distanceKm||0)} km<br><a href="${wazeUrl(city)}" target="_blank" rel="noopener">Abrir no Waze</a>`).addTo(state.routeLayer)}}const located=state.routeStops.filter(validPoint);located.forEach((stop,index)=>{const point=[Number(stop.latitude),Number(stop.longitude)];points.push(point);L.marker(point).bindPopup(`<strong>${index+1}. ${html(stop.name)}</strong><br><a href="${wazeUrl(stop)}" target="_blank" rel="noopener">Navegar com Waze</a>`).addTo(state.routeLayer)});if(located.length>1)L.polyline(located.map((stop)=>[stop.latitude,stop.longitude]),{color:'#142758',weight:4,dashArray:'8 7'}).addTo(state.routeLayer);fitMap(state.routeMap,points,region?[Number(region.hubLatitude),Number(region.hubLongitude)]:[-22.7,-46.4])}

async function loadLiveData(){try{const [prospectRows,visitRows,dashboard]=await Promise.all([api('/api/prospects'),api('/api/visits'),api('/api/dashboard')]);prospects.splice(0,prospects.length,...prospectRows.map(toProspect));visits.splice(0,visits.length,...visitRows.map(toVisit));state.dashboard=dashboard;state.selected=prospects[0]?.id||null;$('#navProspectCount').textContent=dashboard.prospects||0;const metrics=$$('.metric-card strong');if(metrics[0])metrics[0].textContent=number(dashboard.prospects);if(metrics[1])metrics[1].textContent=number(dashboard.high_priority);if(metrics[2])metrics[2].textContent=number(dashboard.customers);if(metrics[3])metrics[3].textContent=number(dashboard.mapped_cities);$('#overviewView .page-intro p:not(.eyebrow)').innerHTML=dashboard.prospects?`Há <strong>${number(dashboard.high_priority)}</strong> oportunidades de alta prioridade na fila real.`:'<strong>Nenhum prospect externo foi carregado.</strong> Os territórios e clientes podem ser usados agora; para descobrir empresas novas ainda é necessária uma fonte empresarial.';$('#regionDataStatus').textContent=`${number(dashboard.synced_regions)} regiões · ${number(dashboard.mapped_cities)} cidades`;$('#customerDataStatus').textContent=`${number(dashboard.customers)} clientes cadastrados no ERP`;$('#syncStatus').textContent=dashboard.last_sync?`Atualizado ${new Date(dashboard.last_sync).toLocaleString('pt-BR')}`:'Ainda não sincronizado';renderPriorities();renderProspects();renderVisits();renderOverviewMap();renderRoute()}catch(error){showToast(`Dados indisponíveis: ${error.message}`)}}
async function loadRegions(){const radius=Number($('#regionRadius')?.value||50);$('#regionRadiusValue').textContent=`${radius} km`;try{state.regions=await api(`/api/regions?radiusKm=${radius}`)}catch{state.regions=[]}renderRegions();renderOverviewMap();renderRouteMap()}
function renderRegions(){const select=$('#regionSelect');if(!select)return;const previous=select.value;select.innerHTML=state.regions.length?state.regions.map((region)=>`<option value="${html(region.id)}">${html(region.name)} · polo ${html(region.hubCity)}/${html(region.hubState)}</option>`).join(''):'<option value="">Nenhuma região sincronizada</option>';if(state.regions.some((region)=>region.id===previous))select.value=previous;const region=selectedRegion();if(!region){$('#regionCities').innerHTML='<span class="city-pill muted">Aguardando sincronização</span>';return}$('#regionHelp').textContent=`${region.cities.length} cidades até ${region.radiusKm} km · vendedor ${region.sellerName||'não informado'} · fonte ${region.sourceLabel||'não identificada'}.`;$('#regionCities').innerHTML=region.cities.length?region.cities.map((city)=>`<button class="city-pill ${city.source==='potential'?'expanded':''}" data-city-lat="${city.latitude}" data-city-lng="${city.longitude}">${html(city.city)}/${html(city.state)} · ${Math.round(city.distanceKm||0)} km</button>`).join(''):'<span class="city-pill muted">Nenhuma cidade neste raio</span>';$('#routeRegionName').textContent=region.name}
function renderPriorities(){$('#priorityList').innerHTML=prospects.length?prospects.slice(0,5).map((p,i)=>`<div class="priority-item" data-select="${p.id}"><span class="priority-rank">${String(i+1).padStart(2,'0')}</span><div><h3>${html(p.name)}</h3><p>${html(p.segment)} · ${html(p.cityName)}</p></div><div class="priority-score" style="--score:${p.score}"><span>${p.score}</span></div></div>`).join(''):'<div class="empty-state" style="display:block"><h3>Sem prospects</h3><p>Conecte uma fonte externa de empresas ou cadastre oportunidades.</p></div>';$('.count-badge').textContent=Math.min(5,prospects.length)}
function renderProspects(){const term=$('#prospectSearch').value.trim().toLowerCase(),segment=$('#segmentFilter').value,priority=$('#priorityFilter').value;const filtered=prospects.filter((p)=>(!state.regionFilter||state.regionFilter.includes(p.id))&&(!term||`${p.name} ${p.city} ${p.cnpj}`.toLowerCase().includes(term))&&(segment==='all'||p.segment===segment)&&(priority==='all'||p.priority===priority));$('#prospectRows').innerHTML=filtered.map((p)=>`<div class="prospect-row ${p.id===state.selected?'selected':''}" data-select="${p.id}"><div class="company-cell"><span class="company-logo" style="background:${p.color}">${p.initials}</span><div><strong>${html(p.name)}</strong><small>${html(p.segment)} · ${html(p.city)}</small></div></div><div class="fit-score">${p.score}%<small>${priorityLabel(p.priority)} prioridade</small></div><div class="potential-cell"><strong>${html(p.potential)}</strong><small>estimativa orientativa</small></div><div class="distance">${validPoint(p)?'Geolocalizado':'—'}<small>${validPoint(p)?'pronto para mapa':'sem coordenadas'}</small></div><span class="status-chip ${p.priority}">${html(p.status)}</span><button class="row-more" aria-label="Mais ações">•••</button></div>`).join('');$('#prospectEmpty').style.display=filtered.length?'none':'block';$('#clearRegionFilter').style.display=state.regionFilter?'flex':'none';renderDetail()}
function renderDetail(){const p=prospects.find((item)=>item.id===state.selected)||prospects[0];if(!p){$('#prospectDetail').innerHTML='<div class="empty-state" style="display:block"><h3>Nenhum prospect cadastrado</h3><p>A base de clientes exclui quem já foi abordado; uma fonte empresarial externa deve fornecer candidatos novos.</p></div>';return}$('#prospectDetail').innerHTML=`<div class="detail-cover"><div class="detail-logo" style="background:${p.color}">${p.initials}</div></div><div class="detail-body"><span class="status-chip ${p.priority}">${priorityLabel(p.priority).toUpperCase()} PRIORIDADE</span><h2>${html(p.name)}</h2><p class="sub">${html(p.segment)} · ${html(p.city)}</p><div class="detail-score"><div><span>Aderência</span><strong>${p.score}%</strong></div><div><span>Potencial mensal</span><strong>${html(p.potential)}</strong></div></div><div class="detail-section"><h3>Por que recomendamos</h3>${p.reasons.map((reason)=>`<div class="reason"><i>✓</i><span>${html(reason)}</span></div>`).join('')}</div><div class="detail-section"><h3>Cadastro</h3><div class="reason"><i>•</i><span>${html(p.cnpj)}<br>${html(p.address)}</span></div></div><div class="detail-actions"><button class="primary-button" data-action="add-to-route">Adicionar à rota</button></div></div>`}
function distanceKm(a,b){const r=6371,dLat=(b.latitude-a.latitude)*Math.PI/180,dLon=(b.longitude-a.longitude)*Math.PI/180,la1=a.latitude*Math.PI/180,la2=b.latitude*Math.PI/180;return 2*r*Math.asin(Math.sqrt(Math.sin(dLat/2)**2+Math.cos(la1)*Math.cos(la2)*Math.sin(dLon/2)**2))}
function routeDistance(){const located=state.routeStops.filter(validPoint);return located.slice(1).reduce((sum,item,index)=>sum+distanceKm(located[index],item),0)}
function persistDraft(){localStorage.setItem('radar-route-draft',JSON.stringify(state.routeStops))}
function wazeUrl(stop){const params=new URLSearchParams({navigate:'yes',utm_source:'radar_comercial'});if(validPoint(stop))params.set('ll',`${Number(stop.latitude)},${Number(stop.longitude)}`);else params.set('q',[stop.address,stop.cityName||stop.city,stop.state].filter(Boolean).join(', '));return `https://waze.com/ul?${params}`}
function whatsappRouteUrl(){const lines=['Rota comercial programada','','O Waze abre cada destino separadamente:',''];state.routeStops.forEach((stop,index)=>lines.push(`${index+1}. ${stop.name}`,wazeUrl(stop),''));return `https://wa.me/?text=${encodeURIComponent(lines.join('\n').trim())}`}
function renderRoute(){const stops=state.routeStops;$('#routeStops').innerHTML=stops.length?stops.map((stop,index)=>`<div class="route-stop prospect"><span class="stop-index">${index+1}</span><div><h3>${html(stop.name)}</h3><p>${html([stop.address,stop.cityName||stop.city,stop.state].filter(Boolean).join(' · '))}</p></div><button class="row-more" data-remove-stop="${html(stop.id)}" aria-label="Remover">×</button><span class="stop-tag">PROSPECT</span><a class="waze-link" href="${wazeUrl(stop)}" target="_blank" rel="noopener">Abrir no Waze</a></div>`).join(''):'<div class="empty-state" style="display:block"><h3>Rota vazia</h3><p>Adicione prospects da fila; nenhuma parada de demonstração será exibida.</p></div>';$('#routeStopCount').textContent=stops.length;$('#routeLocated').textContent=stops.filter(validPoint).length;$('#routeDistance').textContent=`${routeDistance().toFixed(1).replace('.',',')} km`;$('#routeDraftCount').textContent=stops.length;$('#routeDraftTitle').textContent=stops.length?`${stops.length} parada${stops.length>1?'s':''} na rota`:'Nenhuma parada adicionada';$('#routeDraftInfo').textContent=stops.length?`${stops.filter(validPoint).length} com coordenadas prontas para o mapa`:'Escolha prospects reais para montar a navegação.';persistDraft();renderRouteMap()}
function renderVisits(term=''){term=term.toLowerCase();const filtered=visits.filter((v)=>`${v.company} ${v.seller} ${v.result}`.toLowerCase().includes(term));$('#visitRows').innerHTML=filtered.length?filtered.map((v)=>`<div class="visit-row"><div><strong>${v.date}</strong><small>${v.time}</small></div><div><strong>${html(v.company)}</strong><small>${html(v.city)}</small></div><div><strong>${html(v.seller)}</strong><small>${v.initials}</small></div><span class="result-chip ${v.kind}">${html(v.result)}</span><div><strong>${html(v.next.split(' · ')[0])}</strong><small>${html(v.next.split(' · ')[1]||'')}</small></div></div>`).join(''):'<div class="empty-state" style="display:block"><h3>Nenhuma visita registrada</h3><p>Os registros reais aparecerão aqui.</p></div>';const stats=$$('.visit-stats strong');if(stats[0])stats[0].textContent=visits.length;if(stats[1])stats[1].textContent=visits.filter((v)=>v.result!=='Decisor ausente').length;if(stats[2])stats[2].textContent=visits.filter((v)=>v.result.includes('Oportunidade')).length;if(stats[3])stats[3].textContent=visits.length?`${Math.round(visits.filter((v)=>v.result.includes('Oportunidade')).length/visits.length*100)}%`:'0%'}

const viewMeta={overview:['Operação comercial','Visão geral'],prospects:['Inteligência comercial','Prospects'],routes:['Planejamento','Planejar rota'],visits:['Retorno de campo','Visitas']};
function setView(view){if(!viewMeta[view])return;state.view=view;$$('.view').forEach((item)=>item.classList.remove('active'));$(`#${view}View`).classList.add('active');$$('.nav-item[data-view]').forEach((item)=>item.classList.toggle('active',item.dataset.view===view));$('#viewEyebrow').textContent=viewMeta[view][0];$('#viewTitle').textContent=viewMeta[view][1];$('.sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});setTimeout(()=>{state.overviewMap?.invalidateSize();state.routeMap?.invalidateSize();if(view==='routes')renderRouteMap()},150)}
function showToast(message){const toast=$('#toast');$('span',toast).textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),3500)}
function openModal(content){$('#modalContent').innerHTML=content;$('#modalBackdrop').classList.add('open');$('#modalBackdrop').setAttribute('aria-hidden','false');setTimeout(()=>$('.modal input,.modal select')?.focus(),100)}
function closeModal(){$('#modalBackdrop').classList.remove('open');$('#modalBackdrop').setAttribute('aria-hidden','true')}
function prospectForm(){return `<p class="eyebrow">NOVO CADASTRO</p><h2 id="modalTitle">Adicionar prospect</h2><p class="lead">Consulte pontualmente CNPJ ou CEP na BrasilAPI para preencher o cadastro. Não fazemos varredura automatizada.</p><form id="prospectForm"><div class="form-grid"><div class="form-field full"><label>CNPJ</label><div class="lookup-field"><input name="cnpj" placeholder="00.000.000/0001-00"><button type="button" class="secondary-button" data-action="lookup-cnpj">Consultar</button></div></div><div class="form-field full"><label>Empresa</label><input name="name" required></div><div class="form-field"><label>Segmento / CNAE</label><input name="segment"></div><div class="form-field"><label>Prioridade</label><select name="priority"><option value="medium">Média</option><option value="high">Alta</option><option value="low">Baixa</option></select></div><div class="form-field full"><label>CEP</label><div class="lookup-field"><input name="postalCode" placeholder="00000-000"><button type="button" class="secondary-button" data-action="lookup-cep">Consultar</button></div></div><div class="form-field"><label>Cidade</label><input name="city" required></div><div class="form-field"><label>UF</label><input name="state" maxlength="2" required></div><div class="form-field full"><label>Endereço</label><input name="address"></div><div class="form-field full"><label>Observações</label><textarea name="notes"></textarea></div></div><p id="lookupStatus" class="lookup-status"></p><div class="modal-footer"><button type="button" class="secondary-button" data-action="close-modal">Cancelar</button><button class="primary-button">Salvar prospect</button></div></form>`}
async function lookupProspect(kind){const form=$('#prospectForm');if(!form)return;const field=kind==='cnpj'?form.elements.cnpj:form.elements.postalCode;const status=$('#lookupStatus');status.textContent='Consultando BrasilAPI…';try{const data=await api(`/api/lookup/${kind}/${encodeURIComponent(field.value)}`);if(kind==='cnpj'){form.elements.name.value=data.tradeName||data.companyName||'';form.elements.segment.value=data.activity||'';form.elements.postalCode.value=data.postalCode||'';form.elements.city.value=data.city||'';form.elements.state.value=data.state||'';form.elements.address.value=data.address||''}else{form.elements.city.value=data.city||'';form.elements.state.value=data.state||'';form.elements.address.value=[data.street,data.neighborhood].filter(Boolean).join(', ')}status.textContent=`Dados preenchidos por ${data.source}. Revise antes de salvar.`}catch(error){status.textContent=error.message}}
document.addEventListener('click',(event)=>{const action=event.target.closest('[data-action]')?.dataset.action;if(!['lookup-cnpj','lookup-cep'].includes(action))return;event.preventDefault();event.stopImmediatePropagation();lookupProspect(action==='lookup-cnpj'?'cnpj':'cep')},true);
document.addEventListener('submit',async(event)=>{if(event.target.id!=='prospectForm')return;event.preventDefault();event.stopImmediatePropagation();const d=Object.fromEntries(new FormData(event.target));try{await api('/api/prospects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({companyName:d.name,segment:d.segment,city:d.city,state:d.state,postalCode:d.postalCode,address:d.address,cnpj:d.cnpj,priority:d.priority,notes:d.notes})});closeModal();await loadLiveData();setView('prospects');showToast('Prospect adicionado.')}catch(error){showToast(error.message)}},true);
function visitForm(){return `<p class="eyebrow">RETORNO DE CAMPO</p><h2 id="modalTitle">Registrar visita</h2><form id="visitForm"><div class="form-grid"><div class="form-field full"><label>Empresa</label><select name="company">${prospects.map((p)=>`<option>${html(p.name)}</option>`).join('')}</select></div><div class="form-field"><label>Resultado</label><select name="result"><option>Contato realizado</option><option>Oportunidade aberta</option><option>Decisor ausente</option><option>Sem aderência</option></select></div><div class="form-field"><label>Próxima ação</label><input name="next"></div><div class="form-field full"><label>Notas</label><textarea name="notes"></textarea></div></div><div class="modal-footer"><button type="button" class="secondary-button" data-action="close-modal">Cancelar</button><button class="primary-button">Registrar visita</button></div></form>`}
function importModal(){return `<p class="eyebrow">ENTRADA DE DADOS</p><h2 id="modalTitle">Importar planilha</h2><p class="lead">Para a planilha oficial, use “Sincronizar planilha”. Esta opção aceita outras bases.</p><form id="importForm"><div class="form-grid"><div class="form-field full"><label>Tipo</label><select name="sourceType"><option value="erp">Clientes do ERP</option><option value="routes">Rotas</option><option value="candidates">Candidatos externos</option></select></div><div class="form-field full"><label>Link do Google Sheets</label><input type="url" name="googleSheetUrl"></div><div class="form-field full"><label>Ou arquivo Excel</label><input type="file" name="file" accept=".xlsx"></div><div class="form-field full"><label>Aba</label><input name="sheetName"></div></div><div id="importResult"></div><div class="modal-footer"><button type="button" class="secondary-button" data-action="close-modal">Cancelar</button><button class="primary-button">Processar</button></div></form>`}
function territoryModal(){const region=selectedRegion();return `<p class="eyebrow">COBERTURA COMERCIAL</p><h2 id="modalTitle">${html(region?.name||'Territórios')}</h2><p class="lead">Dados vindos da aba Varejo.</p><div class="form-grid"><div class="form-field full"><label>Cidade-polo</label><input readonly value="${html(region?`${region.hubCity}/${region.hubState}`:'Não sincronizado')}"></div><div class="form-field"><label>Vendedor externo</label><input readonly value="${html(region?.sellerName||'Não informado')}"></div><div class="form-field"><label>Especialista</label><input readonly value="${html(region?.specialistName||'Não informado')}"></div></div>`}
function setLocationStatus(title,message,active=false){$('#locationTitle').textContent=title;$('#locationStatus').textContent=message;$('.location-bar').classList.toggle('active',active)}
function useGeolocation(){if(!window.isSecureContext||!navigator.geolocation){showToast('Geolocalização requer HTTPS e um navegador compatível.');return}setLocationStatus('Obtendo localização…','Confirme a permissão no navegador.');navigator.geolocation.getCurrentPosition(async({coords})=>{state.userLocation={latitude:coords.latitude,longitude:coords.longitude,accuracy:coords.accuracy};setLocationStatus('Localização ativa',`Precisão aproximada de ${Math.round(coords.accuracy)} m`,true);if(state.routeMap)L.marker([coords.latitude,coords.longitude]).bindPopup('Minha localização').addTo(state.routeLayer);try{const nearby=await api(`/api/prospects/nearby?lat=${coords.latitude}&lng=${coords.longitude}&radiusKm=${Number($('#regionRadius').value)}`);state.nearbyProspectIds=nearby.map((item)=>item.id);$('#nearbyProspectsButton').disabled=false;$('#nearbyProspectsButton').textContent=`Ver ${nearby.length} prospects próximos`}catch(error){showToast(error.message)}},()=>showToast('Não foi possível obter a localização.'),{enableHighAccuracy:true,timeout:12000,maximumAge:300000})}

document.addEventListener('click',async(event)=>{const nav=event.target.closest('[data-view],[data-view-link]');if(nav){setView(nav.dataset.view||nav.dataset.viewLink);return}const select=event.target.closest('[data-select]');if(select){state.selected=select.dataset.select;renderProspects();if(state.view==='overview')setView('prospects');return}const remove=event.target.closest('[data-remove-stop]');if(remove){state.routeStops=state.routeStops.filter((stop)=>stop.id!==remove.dataset.removeStop);renderRoute();return}const city=event.target.closest('[data-city-lat]');if(city&&state.routeMap){state.routeMap.setView([Number(city.dataset.cityLat),Number(city.dataset.cityLng)],11);return}const action=event.target.closest('[data-action]')?.dataset.action;if(!action)return;if(action==='new-prospect')openModal(prospectForm());else if(action==='register-visit')prospects.length?openModal(visitForm()):showToast('Cadastre um prospect antes de registrar a visita.');else if(action==='import-data')openModal(importModal());else if(action==='close-modal')closeModal();else if(action==='open-territory'||action==='edit-route')openModal(territoryModal());else if(action==='add-to-route'){const p=prospects.find((item)=>item.id===state.selected);if(!p)return showToast('Selecione um prospect.');if(!state.routeStops.some((stop)=>stop.id===p.id))state.routeStops.push({...p});renderRoute();showToast(`${p.name} adicionado à rota.`)}else if(action==='add-route-stop'){setView('prospects');showToast('Escolha um prospect real e clique em “Adicionar à rota”.')}else if(action==='optimize-route'){const located=state.routeStops.filter(validPoint);if(located.length<2)return showToast('São necessárias ao menos duas paradas com coordenadas.');const ordered=[located.shift()];while(located.length){const from=ordered.at(-1);located.sort((a,b)=>distanceKm(from,a)-distanceKm(from,b));ordered.push(located.shift())}state.routeStops=[...ordered,...state.routeStops.filter((stop)=>!validPoint(stop))];renderRoute();showToast('Paradas ordenadas pela menor distância geográfica aproximada.')}else if(action==='share-whatsapp'){if(!state.routeStops.length)return showToast('Adicione paradas antes de compartilhar.');window.open(whatsappRouteUrl(),'_blank','noopener')}else if(action==='sync-sheet'){const button=event.target.closest('button');button.disabled=true;button.textContent='Sincronizando…';try{await api('/api/sync/google-sheet',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});await Promise.all([loadLiveData(),loadRegions()]);showToast('Planilha Varejo e Base de clientes sincronizadas.')}catch(error){showToast(error.message)}finally{button.disabled=false;button.textContent='Sincronizar planilha'}}else if(action==='use-geolocation')useGeolocation();else if(action==='view-nearby-prospects'){state.regionFilter=state.nearbyProspectIds;setView('prospects');renderProspects()}else if(action==='view-region-prospects'){const region=selectedRegion();if(!region)return showToast('Sincronize a planilha primeiro.');state.regionFilter=region.prospectIds||[];setView('prospects');renderProspects();showToast(`${region.prospectCount||0} prospects no raio.`)}else if(action==='clear-region-filter'){state.regionFilter=null;renderProspects()}else if(action==='recenter')renderRouteMap();else if(action==='user-menu')api('/api/auth/logout',{method:'POST'}).finally(()=>window.location.replace('/login.html'));else showToast('Ação ainda não configurada.')});
$('#modalBackdrop').addEventListener('click',(event)=>{if(event.target===$('#modalBackdrop'))closeModal()});
document.addEventListener('submit',async(event)=>{event.preventDefault();const form=event.target;if(form.id==='prospectForm'){try{const d=Object.fromEntries(new FormData(form));await api('/api/prospects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({companyName:d.name,segment:d.segment,city:d.city,state:d.state,cnpj:d.cnpj,priority:d.priority,notes:d.notes})});closeModal();await loadLiveData();setView('prospects');showToast('Prospect adicionado.')}catch(error){showToast(error.message)}}if(form.id==='visitForm'){try{const d=Object.fromEntries(new FormData(form)),p=prospects.find((item)=>item.name===d.company);await api('/api/visits',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prospectId:p?.id,companyName:d.company,city:p?.cityName,result:d.result,nextAction:d.next,notes:d.notes})});closeModal();await loadLiveData();setView('visits');showToast('Visita registrada.')}catch(error){showToast(error.message)}}if(form.id==='importForm'){const button=form.querySelector('button[type="submit"]');button.disabled=true;try{const result=await api('/api/imports',{method:'POST',body:new FormData(form)});$('#importResult').innerHTML=`<div class="import-summary"><strong>${result.total} linhas</strong><br>${result.accepted} aceitas · ${result.duplicate} duplicadas · ${result.rejected} rejeitadas</div>`;await Promise.all([loadLiveData(),loadRegions()]);showToast('Importação concluída.')}catch(error){showToast(error.message)}finally{button.disabled=false}}});
$('#prospectSearch').addEventListener('input',renderProspects);$('#segmentFilter').addEventListener('change',renderProspects);$('#priorityFilter').addEventListener('change',renderProspects);$('#visitSearch').addEventListener('input',(event)=>renderVisits(event.target.value));$('#globalSearch').addEventListener('input',(event)=>{if(event.target.value){setView('prospects');$('#prospectSearch').value=event.target.value;renderProspects()}});$('#regionSelect').addEventListener('change',()=>{renderRegions();renderRouteMap()});$('#regionRadius').addEventListener('input',()=>{$('#regionRadiusValue').textContent=`${$('#regionRadius').value} km`});$('#regionRadius').addEventListener('change',loadRegions);$('.mobile-menu').addEventListener('click',()=>$('.sidebar').classList.toggle('open'));document.addEventListener('keydown',(event)=>{if(event.key==='Escape')closeModal();if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();$('#globalSearch').focus()}});
prepareLiveUi();initMaps();renderPriorities();renderProspects();renderRoute();renderVisits();Promise.all([loadLiveData(),loadRegions()]);
